<?php
require_once __DIR__.'/../../app/layout.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=$_POST['type']??'';$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($type==='job'&&in_array($status,['Aktif','Ditangguhkan'],true)){$st=db()->prepare('UPDATE jobs SET status=? WHERE id=?');$st->execute([$status,$id]);flash('success','Status lowongan diperbarui.');}if($type==='user'&&in_array($status,['Aktif','Ditangguhkan'],true)){$st=db()->prepare("UPDATE users SET status=? WHERE id=? AND role<>'admin'");$st->execute([$status,$id]);flash('success','Status akun diperbarui.');}redirect('admin/dashboard.php');}
$counts=['users'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),'candidates'=>(int)db()->query("SELECT COUNT(*) FROM users WHERE role='candidate'")->fetchColumn(),'companies'=>(int)db()->query("SELECT COUNT(*) FROM users WHERE role='company'")->fetchColumn(),'jobs'=>(int)db()->query('SELECT COUNT(*) FROM jobs')->fetchColumn(),'apps'=>(int)db()->query('SELECT COUNT(*) FROM applications')->fetchColumn()];$jobs=db()->query("SELECT j.*,COALESCE(cp.company_name,u.name) company FROM jobs j JOIN users u ON u.id=j.company_id LEFT JOIN company_profiles cp ON cp.user_id=u.id ORDER BY j.created_at DESC LIMIT 10")->fetchAll();$users=db()->query("SELECT id,name,email,role,status FROM users ORDER BY created_at DESC LIMIT 10")->fetchAll();page_header('Dashboard admin');?>
<section class="dashboard-head"><div class="container"><span class="eyebrow">PANEL ADMINISTRATOR</span><h1>Ringkasan platform</h1><p>Pantau ekosistem dan moderasi konten untuk menjaga kualitas informasi.</p></div></section><section class="section"><div class="container"><div class="metrics five"><?php foreach(['Total pengguna'=>$counts['users'],'Pencari kerja'=>$counts['candidates'],'Perusahaan'=>$counts['companies'],'Lowongan'=>$counts['jobs'],'Lamaran'=>$counts['apps']] as $k=>$v):?><div><small><?=e($k)?></small><b><?=$v?></b><span>Data platform</span></div><?php endforeach;?></div><div class="dashboard-grid"><div class="panel"><h2>Moderasi lowongan</h2><div class="table-wrap"><table><tr><th>Lowongan</th><th>Perusahaan</th><th>Status / aksi</th></tr><?php foreach($jobs as $j):?><tr><td><?=e($j['title'])?></td><td><?=e($j['company'])?></td><td><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="type" value="job"><input type="hidden" name="id" value="<?=(int)$j['id']?>"><select name="status" aria-label="Status lowongan"><?php foreach(['Aktif','Ditangguhkan'] as $s):?><option <?=$j['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-outline btn-sm">Simpan</button></form></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Pengguna terbaru</h2><div class="table-wrap"><table><tr><th>Pengguna</th><th>Peran</th><th>Status</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['name'])?><small><?=e($u['email'])?></small></td><td><?=e($u['role'])?></td><td><?php if($u['role']!=='admin'):?><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="type" value="user"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><select name="status" aria-label="Status pengguna"><?php foreach(['Aktif','Ditangguhkan'] as $s):?><option <?=$u['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-outline btn-sm">Simpan</button></form><?php else:?><span class="badge badge-success">Admin</span><?php endif;?></td></tr><?php endforeach;?></table></div></div></div></div></section><?php page_footer();?>
